from __future__ import annotations

from datetime import datetime
from typing import Any, Dict, List, Optional, Sequence

from shopkit.promotions.coupons import FIXED, PERCENT, Coupon, CouponRejected, coupon_is_active, normalize_code
from shopkit.utils.numbers import apply_rate


def coupon_savings(
    items: Sequence[Any],
    products: Dict[str, Any],
    code: str,
    coupons: Dict[str, Coupon],
    engine: Any,
    ship_to: str,
    weight_g: int,
    at: Optional[datetime] = None,
) -> int:
    """Return the saving in cents that *code* would give on this cart.

    The calculation mirrors the cart page: the coupon's base amount is computed
    against the product subtotal (unit price × quantity per item), and for
    percent coupons it is rounded with the same helper the cart uses.
    Returns 0 when the code is not found, not active, or fails any validation.
    """
    if not code or code is None:
        return 0

    key = normalize_code(code)
    coupon = coupons.get(key)
    if coupon is None:
        return 0

    try:
        if not coupon_is_active(coupon, at=at):
            return 0
    except Exception:
        return 0

    # Compute subtotal in cents from the items and their product records.
    subtotal_cents = 0
    for item in items:
        sku = _item_sku(item)
        qty = _item_qty(item)
        if sku is None or qty <= 0:
            continue
        product = products.get(sku) if products else None
        if product is None:
            continue
        unit_cents = _product_unit_cents(product, engine, ship_to)
        if unit_cents < 0:
            unit_cents = 0
        subtotal_cents += unit_cents * qty

    if subtotal_cents <= 0:
        return 0

    if coupon.kind == PERCENT:
        return apply_rate(subtotal_cents, coupon.percent)
    elif coupon.kind == FIXED:
        # Fixed discount is capped at the subtotal so we never report a negative saving.
        return min(coupon.amount_cents, subtotal_cents)
    else:
        return 0


def _item_sku(item: Any) -> Optional[str]:
    if hasattr(item, "sku"):
        return item.sku
    if isinstance(item, dict):
        return item.get("sku")
    return None


def _item_qty(item: Any) -> int:
    if hasattr(item, "qty"):
        return int(item.qty)
    if isinstance(item, dict):
        return int(item.get("qty", 1))
    return 1


def _product_unit_cents(product: Any, engine: Any, ship_to: str) -> int:
    if hasattr(product, "price_cents"):
        return int(product.price_cents)
    if isinstance(product, dict):
        return int(product.get("price_cents", 0))
    # Fallback: try to use the pricing engine if the product has the needed shape.
    try:
        if hasattr(engine, "unit_price_cents"):
            return int(engine.unit_price_cents(product, ship_to))
    except Exception:
        pass
    return 0
